import type {ResearchPost} from '../fleet-data';

type Study={slug:string;title:string;excerpt:string;cluster:string;stat:string;service:{slug:string;label:string;title:string;body:string};sections:readonly {heading:string;body:string}[];sources:readonly {name:string;url:string}[]};

const abaOutsourcing={name:'Formal Opinion 08-451: Lawyer Obligations When Outsourcing Legal and Nonlegal Support Services, American Bar Association',url:'https://www.americanbar.org/content/dam/aba/publications/YourABA/201106_08451.authcheckdam.pdf'};
const model53={name:'Model Rule 5.3: Responsibilities Regarding Nonlawyer Assistance, American Bar Association',url:'https://www.americanbar.org/groups/professional_responsibility/publications/model_rules_of_professional_conduct/rule_5_3_responsibilities_regarding_nonlawyer_assistant/'};
const privacy={name:'Data Privacy Act of 2012, Philippines National Privacy Commission',url:'https://privacy.gov.ph/data-privacy-act/'};
const civilRules={name:'Federal Rules of Civil Procedure, United States Courts',url:'https://www.uscourts.gov/forms-rules/current-rules-practice-procedure/federal-rules-civil-procedure'};

const studies:readonly Study[]=[
  {
    slug:'deposition-exhibit-provenance-offshore-research',title:'Deposition exhibit provenance in offshore legal support',excerpt:'A source-lineage study for preparing deposition exhibit inventories while counsel retains selection, use, privilege, and examination decisions.',cluster:'Workflow Design',stat:'Decision focus: can an exhibit inventory remain reconstructable through renaming, pagination, and duplicate handling?',
    service:{slug:'litigation-document-review',label:'Plan a deposition support pilot',title:'Keep exhibit choices and examination strategy with counsel',body:'Define source identities, working-copy rules, exception states, and attorney approval before support prepares an exhibit inventory.'},
    sections:[
      {heading:'The narrow operational question',body:`A deposition team may need hundreds of candidate documents arranged before an examination. The administrative opportunity is real, but so is the risk that a convenient working file loses its origin or that an index silently becomes an exhibit-selection decision. This study asks whether Philippines-based legal support can prepare a candidate exhibit inventory whose entries can be reconstructed from counsel-approved sources. It does not ask support staff to decide relevance, privilege, admissibility, completeness, impeachment value, confidentiality treatment, or the sequence of questioning. Those choices remain with the lawyers responsible for the matter. The unit of analysis is one candidate file moving from an approved source set to a reviewable inventory row. Success means another reviewer can locate the exact source, explain every working-copy change, see unresolved defects, and identify the attorney action that changed a candidate into an approved exhibit. A polished binder without that lineage does not satisfy the method.`},
      {heading:'Source population and sampling method',body:`The proposed pilot uses forty synthetic records distributed across six document families: email with attachments, a multipage agreement, spreadsheets with several worksheets, photographs, prior testimony excerpts, and a produced document bearing an external control number. Deliberate conditions include two visually identical files with different hashes, a filename reused in separate folders, an attachment missing from one family, a document with mixed portrait and landscape pages, an image that contains no embedded text, a superseded draft, and a confidentiality marking. Counsel supplies the candidate population and a frozen manifest. Support does not search outside that population or add an item because it appears useful. A stratified sample ensures that each file type and seeded condition is reviewed rather than allowing common PDFs to dominate the result. This synthetic design tests provenance and exception handling; it cannot estimate defect frequency in a live matter or show that a candidate should be used.`},
      {heading:'Permitted preparation and stop rules',body:`Support may record a stable candidate identifier, original filename, source repository path, supplied control number, byte hash, file type, displayed title, displayed date, page count, family relationship, working-copy filename, and transformation history. It may compare the item against a counsel-approved candidate list, generate a working copy using an approved tool, and flag unreadable pages or inconsistent identifiers. Work stops when a source is missing, a hash changes unexpectedly, a duplicate has competing annotations, a password prevents access, a confidentiality designation conflicts, or an instruction would require choosing substantive content. Support must not remove pages, alter substantive content, decide which version is authoritative, apply an exhibit number without authorization, characterize a document as authentic, or share the set with a witness. A stop is a successful control event when the reason and source are clear. It is not a productivity failure to be hidden.`},
      {heading:'Provenance record design',body:`Each row should connect the frozen source manifest to every derived artifact. Recommended fields include matter identifier, candidate identifier, source-system reference, original filename, original hash, received timestamp, producing party or custodian only as supplied, family identifier, parent identifier, attachment identifier, source control number, displayed date, page count, file type, working-copy hash, transformation tool and version, transformation rule, output filename, exception code, reviewer, attorney disposition, approved exhibit label, and approval time. Original and derived values occupy separate fields. A renamed copy cannot overwrite the original filename, and an attorney label cannot erase the candidate state. If pagination is added, the ledger records whether it is file-level, page-level, or merely a viewer display. This structure lets a reviewer distinguish byte identity from visual similarity and administrative completion from legal approval. It also limits the support role to observations that can be traced to a source.`},
      {heading:'Worked duplicate-file example',body:`Assume the candidate folder contains Contract_Final.pdf twice. One copy came from a produced set and bears a control number in the image footer; the other came from a client folder and has the same page text but a handwritten annotation on page seven. Their filenames and displayed titles match, but their hashes do not. Support records two candidate identities, preserves both source paths, compares page counts, and flags the visual and hash difference. It does not select the cleaner copy, combine the annotation with the produced version, call either file authentic, or describe one as controlling. Counsel can decide whether both belong in review, whether the annotation affects privilege or use, and which source may become an exhibit. If counsel approves one, the approval points to its exact hash and source. The rejected candidate remains in the history so a later reviewer can explain why the seemingly duplicate file was not substituted.`},
      {heading:'How to interpret quality evidence',body:`A low exception count does not prove an accurate inventory; the source population may be simple or workers may have failed to notice differences. A high duplicate count may reflect normal collection structure rather than careless preparation. Hash equality establishes byte identity for the compared files, not authenticity, admissibility, or an unbroken chain before the files entered the frozen set. Page-count agreement does not establish legibility. Text extraction success does not mean an image, annotation, formula, or hidden worksheet was preserved. The useful measures are reconstruction success, unsupported transformations, missed seeded conditions, family-link accuracy, exceptions routed to the correct owner, and attorney corrections by category. Denominators should identify records, pages, and families separately. Timing begins only after the complete approved input is available. These distinctions keep an operational score from becoming an unsupported assertion about the evidence or the underlying case.`},
      {heading:'Authority, facts, and inference',body:`The cited federal rules provide official procedural context for depositions and discovery, while the Federal Rules of Evidence provide context for evidence questions. They do not prescribe this inventory design or approve offshore preparation. ABA Formal Opinion 08-451 and Model Rule 5.3 address supervision and outsourcing responsibilities; they do not decide any matter-specific exhibit question. The Philippines privacy source supplies local accountability context without resolving a particular transfer, client instruction, protective order, or repository configuration. The factual layer in this study is limited to what the files and approved manifest display. The analysis is that preserved lineage and separate approval states make supervision more reviewable. The inference is that this design may reduce substitution and version ambiguity in a bounded pilot. That inference must be tested locally and should not be described as proof of legal compliance, evidentiary reliability, or deposition readiness.`},
      {heading:'Acceptance test and limitations',body:`Run the forty-record pilot with the seeded conditions concealed from the preparer. A second reviewer reconstructs twelve rows across all file types and independently checks hashes, source locations, families, transformations, and exception states. The pilot fails if a source value is overwritten, if a derived file lacks its parent hash, if support resolves a substantive conflict, if a confidentiality exception is bypassed, or if an exhibit label appears without attorney action. Record false merges, false separations, missed pages, broken family links, transformation errors, and unsupported labels. This test cannot establish privilege, authenticity, admissibility, relevance, completeness of discovery, witness familiarity, or appropriate questioning. Tool behavior may vary for spreadsheets, embedded files, image compression, and password protection. Real matters may impose orders or agreements not represented here. The firm must adapt the fields, access, and review to its actual court, client, platform, and instructions.`},
      {heading:'Decision for a legal-support buyer',body:`A buyer can delegate deposition exhibit inventory preparation only as a source-controlled administrative lane. The deliverable is not a finished exhibit set and not a recommendation about use. It is a candidate ledger in which every file has a stable identity, every change is attributable, every uncertainty remains visible, and every exhibit designation comes from a lawyer. Before expanding the lane, the firm should test difficult formats, measure reconstruction rather than speed alone, and confirm that access is restricted to the approved population. The buyer should ask to see how a duplicate, missing attachment, mixed orientation file, and changed hash travel through the workflow. If the answer depends on an experienced worker remembering what to do, the process is not yet durable. If the record itself carries source, transformation, exception, and approval evidence, support can reduce clerical friction while leaving evidentiary and strategic decisions where they belong.`}
    ],
    sources:[abaOutsourcing,model53,privacy,civilRules,{name:'Federal Rules of Evidence, United States Courts',url:'https://www.uscourts.gov/forms-rules/current-rules-practice-procedure/federal-rules-evidence'}]
  },
  {
    slug:'bankruptcy-claim-packet-indexing-offshore-study',title:'Bankruptcy claim packet indexing with offshore legal support',excerpt:'A controlled study of official-form identity, attachment lineage, amendment history, and attorney-owned claim decisions.',cluster:'Scope Benchmarks',stat:'Method focus: test packet reconstruction without delegating creditor, amount, priority, filing, or legal-sufficiency judgments.',
    service:{slug:'case-file-management',label:'Scope a claim-packet indexing lane',title:'Separate packet administration from claim decisions',body:'Build a source register and exception route while counsel controls whether, how, and when any claim is filed or amended.'},
    sections:[
      {heading:'Buyer decision and unit of analysis',body:`Bankruptcy work often arrives as a mixture of notices, account records, contracts, assignments, correspondence, court forms, and later amendments. A firm considering offshore support needs a more precise question than whether an assistant can prepare a proof of claim. This study evaluates only whether support can inventory a counsel-selected packet and expose missing or conflicting source facts before a qualified reviewer makes legal decisions. The unit is one asserted source fact linked to the document and location where it appears. The support role does not identify the proper creditor, calculate the claim, determine secured or priority status, interpret a bar date, choose a form, sign a declaration, file through a court system, or advise a client. The intended output is a packet map with unresolved questions. It is useful when it lets counsel return from a field such as account identifier or stated balance to the exact source without treating that administrative linkage as proof the assertion is legally valid.`},
      {heading:'Constructed packet population',body:`The study uses eight synthetic creditor packets built from public official-form structures and invented commercial records. Each packet contains a notice, an account statement, an agreement, and a candidate official form. Some add an assignment record, payment history, security document, or amendment. Seeded conditions include a creditor name change, redacted personal identifiers, a balance date that differs from the petition date supplied in the exercise, an attachment referenced but absent, inconsistent account endings, a document denominated in another currency, a duplicate statement, and an unsigned assignment page. One packet has two amendments whose filenames sort in the wrong chronological order. The set is purposive, not statistically representative. It tests identity, source dating, version separation, and escalation. It cannot estimate how often real claims contain these conditions, and it deliberately avoids real debtor data, live dockets, or any conclusion about entitlement.`},
      {heading:'Observation rules and prohibited actions',body:`Support may inventory documents, record titles and dates as displayed, preserve identifiers exactly, link amendments, note the period covered by a statement, identify blank fields, and compare an approved checklist with the packet. A copied numeric value retains its label, currency, as-of date, source page, and original formatting. Support may flag arithmetic that does not reproduce using a counsel-supplied formula, but it cannot create a balance or decide which components belong in a claim. It may record that a document displays language such as secured, priority, guarantor, or assignee, but it must not convert that language into a legal classification. Work stops on conflicting creditor identities, unclear account mapping, missing referenced attachments, unapproved personally identifiable information, an uncertain form edition, or a request to file. Only authorized counsel or a designated qualified owner can resolve claim identity, amount, status, evidence sufficiency, signature, amendment, timing, and submission.`},
      {heading:'Packet map and amendment ledger',body:`The packet map needs separate document and field layers. Document fields include packet identifier, source filename, repository path, hash, displayed title, displayed date, received date, page count, document type as supplied, access class, and relationship to another document. Field entries add source document hash, page or section, field label, exact displayed value, normalized copy if authorized, currency, stated as-of date, exception, reviewer, and disposition. An amendment ledger identifies each candidate form or supporting document version without overwriting prior states. It records who supplied the version, when the firm received it, what instruction caused the change, and whether counsel marked it superseded. A status such as source captured means only that the displayed value was recorded. It cannot mean verified debt, complete evidence, allowed claim, timely filing, or approved amendment. Those labels would compress several legal and factual judgments into an administrative cell.`},
      {heading:'Worked identity conflict',body:`Consider a packet in which the agreement names North Harbor Supply LLC, the latest statement uses North Harbor Collections, and an assignment page refers to NHS Receivables Trust but lacks its signature page. The account suffix matches across two documents, while the amounts and dates differ. Support creates separate displayed-name entries tied to each source, records the matching suffix as an observation, and flags the missing page and competing amounts. It does not merge the entities, infer a valid assignment, select the latest amount as the claim, or populate a creditor field. Counsel can evaluate entity status, assignment evidence, petition timing, governing documents, and court requirements. If counsel supplies a decision, the ledger records the approved identity and source basis separately from the original observations. This example tests whether the workflow preserves ambiguity. A system that forces one creditor name before review would create apparent completeness at the cost of hiding the central question.`},
      {heading:'Measurement without legal overclaiming',body:`The pilot measures exact transcription, source-location accuracy, correct version linkage, identifier preservation, missed seeded exceptions, unauthorized normalization, and reviewer reconstruction. Arithmetic reproduction is measured only where counsel supplies a formula and known inputs; it is not called claim validation. A packet with every checklist item present may still be legally deficient, while a sparse packet may be adequate for a purpose counsel understands. More attachments do not mean stronger evidence. A recent statement does not necessarily supply the legally relevant date. An official-form edition number can be compared with the official source, but support should not decide the procedural consequence of a different edition. Results should report denominators for documents, fields, and packets because one large packet could otherwise distort the study. Review time should distinguish administrative correction from substantive lawyer analysis. The aim is to learn whether the prepared map accurately describes its bounded sources.`},
      {heading:'Use of authoritative sources',body:`The United States Courts bankruptcy rules and official-form pages are primary federal judiciary sources for current public materials. They supply the external reference points for form identity and procedure, not a promise that a synthetic packet is file-ready. The Bankruptcy Code published by the House Office of the Law Revision Counsel provides statutory text, but this study does not interpret that text. ABA outsourcing and supervision sources frame responsibility for delegated assistance. The Philippine privacy statute gives local data-processing context, especially relevant to debtor and account information, but it does not resolve the firm's cross-border, contractual, court, or client obligations. Facts in the pilot come from the constructed packet and displayed official-source metadata. The workflow recommendations are operational analysis. Any prediction that the controls will reduce missing evidence is an inference requiring local observation, and it must not be presented as a court-approved practice.`},
      {heading:'Limitations and failure conditions',body:`This study cannot determine whether a person has a claim, who owns it, what amount is owed, whether interest or fees are recoverable, whether security or priority exists, whether evidence is sufficient, whether a deadline applies, or whether a filing or amendment should occur. It does not assess electronic filing credentials, local rules, judge-specific requirements, privacy redactions, or legal consequences of an error. Synthetic records lack the complexity and stakes of live debtor information. Official forms and rules can change, so the firm must check the current authorized source at the time of work. The pilot fails operationally if a source is overwritten, a displayed name is silently standardized, an amount loses its date or currency, a missing page is treated as present, or a packet reaches an approved state without named lawyer action. Sensitive source files require matter-specific access, storage, retention, and disposal controls beyond the fields described here.`},
      {heading:'Pilot gate and buyer conclusion',body:`Have two workers independently map three of the eight packets and compare their records before counsel reveals the seeded conditions. Then ask a reviewer unfamiliar with the preparation to reconstruct twenty fields and the complete amendment history for two packets. Expand only if the reviewer can locate every source, distinguish original from normalized values, see all unresolved identity and version questions, and identify the person authorized to decide them. The buyer should prefer a process that returns a shorter, accurate exception list over one that fills every form field through inference. Offshore support can add value by ordering evidence, preserving source labels, and keeping amendments legible. The firm retains the decision about creditor identity, amount, status, timing, signature, filing, and client communication. The deliverable is therefore a claim packet index for review, not a completed proof of claim and not legal advice about bankruptcy rights or procedure.`}
    ],
    sources:[abaOutsourcing,model53,privacy,{name:'Federal Rules of Bankruptcy Procedure, United States Courts',url:'https://www.uscourts.gov/forms-rules/current-rules-practice-procedure/federal-rules-bankruptcy-procedure'},{name:'Bankruptcy Forms, United States Courts',url:'https://www.uscourts.gov/forms-rules/forms/bankruptcy-forms'},{name:'United States Bankruptcy Code, Office of the Law Revision Counsel',url:'https://uscode.house.gov/view.xhtml?edition=prelim&path=%2Ftitle11'}]
  },
  {
    slug:'uscis-receipt-notice-reconciliation-offshore-research',title:'USCIS receipt-notice reconciliation for offshore case administration',excerpt:'Research on matching filed-package records to agency receipts while attorneys retain status, deadline, eligibility, and response decisions.',cluster:'Workflow Design',stat:'Control question: can receipt facts be reconciled without converting agency text into immigration advice?',
    service:{slug:'immigration-case-administration',label:'Design a receipt reconciliation pilot',title:'Keep immigration interpretation with qualified counsel',body:'Define source documents, privacy limits, mismatch codes, and review owners before support reconciles agency receipts.'},
    sections:[
      {heading:'Why receipt reconciliation needs a boundary',body:`An immigration practice may receive agency notices through mail, online accounts, clients, employers, and counsel. Matching those notices to the firm's filed-package record is administrative work, but the notice may contain dates, classifications, identifiers, requests, transfers, rejections, or other language with legal consequences. This study asks whether offshore support can reconcile displayed receipt facts against a frozen internal manifest without interpreting status or advising a person. The unit is a paired comparison between one agency document and one firm-supplied package record. Support records what each source displays and routes differences. It does not decide whether a filing was accepted, whether status is lawful, whether a deadline runs, whether a classification is correct, whether a response is sufficient, or what the client should do. A successful output is a mismatch ledger a lawyer can reproduce, not a case assessment and not a promise about agency processing.`},
      {heading:'Test design and privacy minimization',body:`The pilot contains thirty invented package manifests and corresponding synthetic notices modeled only at the field level on public USCIS materials. Names, addresses, receipt numbers, registration numbers, employers, dependents, and payment references are fictional. Seeded cases include a transposed receipt number, a shortened beneficiary name, two related forms with different notice dates, a form type mismatch, a duplicate scan, a notice addressed to a prior location, a page missing from a multipage notice, a package with no matching receipt, and a receipt with no listed internal package. One document contains a date near midnight in a different time zone to test faithful transcription rather than conversion. The worker receives only fields necessary for the comparison. The study uses full synthetic documents so no live immigration data enters training. Its results apply to the tested reconciliation mechanics, not USCIS outcomes, real populations, or the frequency of agency errors.`},
      {heading:'Authorized comparison lane',body:`Support may capture the notice title, form identifier as displayed, receipt identifier, received date, notice date, petitioner and beneficiary names as displayed, page count, stated mailing address, source channel, file hash, and related internal package identifier supplied by the firm. It may compare exact values, apply a written name-matching rule that preserves both originals, identify missing pages, and route unmatched records. It cannot log into an agency account unless separately authorized, change an address, interpret a case status, calculate a response or eligibility date, contact USCIS, advise the client, select a form, or submit anything. Terms such as received, rejected, transferred, reopened, or request for evidence are recorded only as document text, not as a support-worker conclusion. Any urgency rule must be supplied and owned by the firm; the worker may route the notice under that rule but cannot decide its legal effect.`},
      {heading:'Reconciliation ledger structure',body:`The ledger separates intake evidence from comparison results. Intake fields include synthetic case identifier, document hash, original filename, source channel, received timestamp, page count, access class, and uploader. Notice-observation fields capture labels and values exactly, with page location. Manifest fields remain in their own columns with source version and preparation date. Comparison fields use narrow codes such as exact match, formatting difference under approved rule, conflicting value, missing manifest, missing notice, incomplete image, duplicate candidate, or requires attorney review. Each exception has an owner, opened time, source links, and disposition. The system retains prior values after correction. A matched receipt number cannot automatically change a case to active, accepted, pending, or complete. Those words carry meaning beyond the byte-level and field-level comparison. The ledger should also restrict exports, avoid unnecessary copies of identifiers, and record access consistently with the firm's privacy and security plan.`},
      {heading:'Family-link edge case',body:`Suppose a firm manifest lists a petition and a related application mailed in one package. Two notices arrive on different days. One matches the petition form and beneficiary name but uses a name abbreviation; the other matches the application form yet displays a receipt identifier differing by one character from the client email transcription. Support records each notice independently, preserves the exact displayed names and identifiers, links both only to the firm-supplied package family, and flags the abbreviation and identifier conflict. It does not assume the notices cover every submitted item, correct the email, declare the package accepted, or infer a processing sequence. Counsel can inspect the scans, filing copy, delivery evidence, account information, and current agency guidance. The later disposition records which value the lawyer approved for internal administration while retaining the conflicting source. This keeps a clerical discrepancy from becoming an undocumented immigration conclusion.`},
      {heading:'Metrics and interpretation',body:`The principal measures are exact-field accuracy, correct document-to-manifest pairing, missed mismatches, false mismatches, page-completeness detection, duplicate handling, preservation of original values, and routing latency under a firm-defined rule. Accuracy is reported by field type because identifiers, names, dates, and form labels have different error patterns. A high matching rate may simply reflect a simple test set. A low rate may reflect deliberately difficult names or poor scans, not worker performance. Receipt pairing does not prove filing completeness or agency acceptance. A displayed date does not tell support which legal deadline applies. Fast routing is useful only if the correct source and exception accompany the alert. The strongest local signal is whether a second reviewer can reproduce the comparison from the same frozen inputs and understand why an item stopped, without needing the preparer's memory or a hidden spreadsheet convention.`},
      {heading:'Primary-source role and uncertainty',body:`USCIS form and filing pages and the USCIS Policy Manual are first-party agency sources. They are checked for public terminology and current reference context, not used here to answer a person's immigration question. The public case-status page demonstrates an official lookup channel, but this pilot does not query real receipt numbers or automate that service. ABA outsourcing and supervision materials frame the lawyer's obligations when nonlawyer assistance is used. The Philippines privacy law is relevant context for handling personal data, but it does not resolve all federal, state, contractual, or cross-border requirements. Facts are limited to displayed synthetic fields and published agency content. The proposed ledger is analysis. It is an inference, not a proven fact, that structured mismatch codes will reduce silent transcription errors. A firm must validate that inference in its own systems under qualified immigration supervision.`},
      {heading:'Limits and safeguards',body:`This design cannot determine immigration status, eligibility, admissibility, work authorization, filing validity, agency error, response sufficiency, deadline calculation, case strategy, or likely outcome. It cannot establish that a notice is authentic merely because fields match. Public USCIS content changes, and case-specific notices or account information may control questions not represented on a general page. Optical character recognition can transpose characters or omit text, so the image remains the source and uncertain values require human review. The process needs strict access, approved transmission, retention, incident response, and identity controls because immigration records contain sensitive personal information. The pilot must stop if live data appears in the synthetic lane, if a worker is asked to interpret agency language, if an unmatched notice is silently forced to a case, or if a status field changes without an authorized firm decision.`},
      {heading:'Acceptance decision',body:`Run the thirty-pair exercise twice: first with exact comparisons, then with only the firm's approved normalization rules. Require a second reviewer to reproduce every mismatch and a lawyer to review all seeded legal-language conditions. The lane is acceptable only if all original values survive, no record is falsely closed, missing pages and unmatched items remain visible, and the worker never supplies a status interpretation. Buyers should examine the exception log, not only the number of receipts processed. They should verify that support cannot contact the agency, change a case, or message a client through the reconciliation role. Used this way, offshore case administration can make incoming evidence easier to find and compare. It cannot replace the attorney who assesses the notice, chooses any response, communicates advice, and owns the consequences of timing or filing decisions.`}
    ],
    sources:[abaOutsourcing,model53,privacy,{name:'USCIS Forms, U.S. Citizenship and Immigration Services',url:'https://www.uscis.gov/forms/all-forms'},{name:'USCIS Policy Manual, U.S. Citizenship and Immigration Services',url:'https://www.uscis.gov/policy-manual'},{name:'Case Status Online, U.S. Citizenship and Immigration Services',url:'https://egov.uscis.gov/'}]
  },
  {
    slug:'trademark-specimen-evidence-inventory-offshore-study',title:'Trademark specimen evidence inventory for offshore legal support',excerpt:'A field-observation study of specimen source, capture context, versioning, and attorney-controlled trademark decisions.',cluster:'Scope Benchmarks',stat:'Boundary test: inventory observed specimen evidence without deciding use, commerce, class, acceptability, or filing strategy.',
    service:{slug:'legal-research-support',label:'Plan a trademark evidence inventory',title:'Preserve observations without making trademark judgments',body:'Set capture rules, source fields, and attorney review gates for a bounded specimen evidence lane.'},
    sections:[
      {heading:'Research question and decision owner',body:`Trademark teams may collect product pages, packaging images, labels, storefront photographs, software screens, service advertisements, and other candidate material for attorney review. The administrative question is whether offshore support can inventory that evidence without deciding what qualifies as a specimen or what should be filed. This study tests a narrow observation-and-provenance lane. Counsel defines the mark, application or registration context, relevant goods or services, approved sources, capture period, and review owner. Support records what the source displays and how the capture was made. It does not decide use in commerce, class coverage, mark presentation, acceptability, dates of first use, ownership, fraud, filing basis, response strategy, or whether a submission should occur. The unit is one captured artifact and its source context. The deliverable is a candidate evidence inventory for legal review, not a conclusion about trademark rights and not a ready-to-file specimen.`},
      {heading:'Evidence population and capture experiment',body:`The experiment uses twenty-four synthetic commercial artifacts hosted in a closed test environment: product-detail pages, checkout screens, downloadable labels, packaging photographs, service pages, app screens, marketplace listings, and archived versions. Conditions include a page where the mark appears only in navigation, a product that is unavailable, an image served from a different host, a dynamically loaded price, a screenshot missing its browser context, a service description below an accordion, two captures with different dates, a mock-up watermark, and a page whose structured data conflicts with visible text. Support receives a written capture protocol and no instruction about legal acceptability. Each artifact is captured by two workers using the same approved environment. The study compares provenance completeness and observation consistency. Because every artifact is invented, it cannot estimate real marketplace practices, establish actual use, or replicate every browser, device, archive, platform, or USPTO examination issue.`},
      {heading:'Observation fields and exclusions',body:`Permitted fields include candidate identifier, URL, capture timestamp and time zone, page title, visible mark text, displayed goods or service wording, price presence as observed, order or contact mechanism as observed, image filename, image URL, viewport, capture tool and version, screenshot hash, full-page or viewport scope, access result, redirects, and visible limitations such as unavailable or mock-up labels. Support may save an authorized PDF or screenshot, preserve the raw capture, and flag missing context. It cannot edit an image to improve the mark, combine separate pages into a purported single specimen, infer that a purchase can be completed, determine whether goods are transported, decide that services are rendered, select a class, or state a first-use date. If a page changes during capture, an element requires an account, geographic results differ, or the source cannot be preserved under the protocol, the record stops in an exception state.`},
      {heading:'Provenance bundle',body:`Each candidate receives a bundle rather than a loose screenshot. The bundle contains the original URL, retrieval timestamp with time zone, redirect chain, response or access result, capture environment, viewport, raw screenshot or PDF hash, visible-text extract when authorized, asset references, protocol version, preparer, and exception notes. A manifest links later annotations without modifying the raw artifact. If counsel requests a crop for convenient review, the crop is a derivative with its own hash and a pointer to the complete capture. An archived page is labeled with both archive timestamp and retrieval timestamp; neither is silently treated as a first-use date. A photograph records who supplied it and the supplied context rather than inventing location or sales facts. These fields allow counsel to evaluate the candidate in context while making clear which statements are direct observations, which were provided by a client, and which remain unknown.`},
      {heading:'Dynamic-page example',body:`Imagine a synthetic product page that displays the mark, item image, description, and an add-to-cart button. On initial load the price is blank; a script fills it after several seconds. The item is labeled temporarily unavailable, while structured data contains an in-stock value. One worker captures immediately and another after the script runs. Support preserves both timestamps and screenshots, records the conflicting visible and structured observations, and flags the protocol ambiguity. It does not choose the later capture, alter the availability label, claim the product was purchasable, or infer use in commerce. Counsel can decide whether additional evidence is needed, whether the artifact is relevant to the specific filing question, and what representations can truthfully be made. The worked example shows why a screenshot without environment and timing can look definitive while omitting the conditions that produced it.`},
      {heading:'Consistency measures',body:`The analysis compares whether two workers captured the same approved URL, timestamp precision, redirect outcome, visible mark string, source scope, screenshot dimensions, asset references, limitation flags, and hash. Differences are categorized as source change, timing behavior, environment behavior, protocol ambiguity, or preparer error. A single agreement percentage would conceal those causes. The reviewer also checks whether derivatives retain links to raw artifacts and whether any unsupported legal labels appear. More screenshots do not create stronger evidence if they repeat the same uncertain source. A complete URL does not prove the page was publicly available at another date. Matching visible text does not establish that goods or services meet an application description. The useful operational finding is whether the team can reconstruct what was displayed during a defined capture and can recognize when the protocol or source prevents a reliable administrative record.`},
      {heading:'Sources and analytical limits',body:`USPTO trademark specimen and application guidance and the Trademark Manual of Examining Procedure are first-party agency materials. They give qualified reviewers current public reference points, but this study neither interprets them for a matter nor suggests that the USPTO endorses this workflow. ABA supervision and outsourcing materials frame responsibility for nonlawyer help. The Philippines privacy source matters when captures or client-supplied materials contain personal information, though it does not answer every data or confidentiality question. Direct facts in the experiment are the synthetic page responses, visible content, files, and recorded capture conditions. The proposed separation of raw and derived artifacts is analytical design. The claim that this separation improves later review is a reasoned inference that must be evaluated locally. None of the sources establishes ownership, registrability, infringement, priority, truthful use, or acceptability of any candidate.`},
      {heading:'Limitations and safeguards',body:`A controlled website cannot reproduce every content-delivery network, personalized page, marketplace restriction, mobile application, authenticated service, physical packaging condition, or archive limitation. Screenshots can omit interactions, metadata, hidden elements, or changes outside the viewport. Automated capture may violate a site's terms or technical controls, so the firm must authorize sources and methods before collection. Support must not bypass authentication, geographic restrictions, robots controls, or access barriers. Candidate material may include customer data, account details, or third-party content requiring limited access. Public USPTO materials can change, and a matter may involve jurisdiction-specific or fact-specific rules beyond them. This method cannot determine whether evidence is truthful, representative, current, legally sufficient, or appropriate to submit. It also cannot supply client declarations or cure missing business facts. Every legal characterization and filing representation remains with qualified counsel and the client.`},
      {heading:'Buyer acceptance test',body:`Use the twenty-four artifacts to test repeatability across two preparers and one independent reviewer. Acceptance requires complete raw-artifact lineage, no overwritten captures, correct time-zone recording, visible conflict flags, preserved redirects, derivative links, and zero unsupported labels such as acceptable, in use, valid, or file-ready. Ask the reviewer to reconstruct four captures using only the manifest and saved bundle. Reject the lane if a screenshot cannot be tied to its URL and conditions, if mock-up or unavailable indicators disappear, or if a worker chooses among conflicting sources. A careful offshore support role can reduce the clerical burden of gathering and organizing candidate evidence. Its value lies in making context and uncertainty easier for the attorney to inspect. The buyer should purchase that bounded administrative capability, not a promise that remote collection can answer the trademark question or substitute for counsel's factual inquiry and legal judgment.`}
    ],
    sources:[abaOutsourcing,model53,privacy,{name:'Trademark Specimens, United States Patent and Trademark Office',url:'https://www.uspto.gov/trademarks/laws/specimen-refusal-and-how-overcome-refusal'},{name:'Trademark Manual of Examining Procedure, United States Patent and Trademark Office',url:'https://tmep.uspto.gov/RDMS/TMEP/current'}]
  },
  {
    slug:'service-of-process-proof-record-offshore-research',title:'Service-of-process proof records in offshore legal support',excerpt:'A source-comparison study for organizing service evidence while lawyers control validity, deadlines, sufficiency, and procedural response.',cluster:'Hiring Controls',stat:'Governance focus: keep service events attributable without allowing an administrative log to declare service valid.',
    service:{slug:'case-file-management',label:'Design a service-record workflow',title:'Make service evidence reviewable without declaring validity',body:'Define approved sources, event fields, discrepancy codes, and attorney review before support maintains service records.'},
    sections:[
      {heading:'Decision framed as recordkeeping',body:`Service records can include instructions, summonses, complaints, vendor status messages, declarations, affidavits, receipts, photographs, correspondence, docket entries, and returned mail. Their dates and descriptions may affect urgent legal decisions, which makes careless abstraction risky. This study asks whether Philippines-based support can organize those source events in a way that helps counsel review them without deciding whether service was valid, timely, complete, waived, cured, or legally consequential. The unit is one observed event tied to one source. Support can show that a vendor message reported an attempt or that a signed document displays a date. It cannot transform the report into a legal conclusion about service. Counsel selects the governing sources and owns every procedural calculation, challenge, representation, filing, and client communication. The output is therefore an evidence chronology and discrepancy queue, not proof that service occurred as a matter of law.`},
      {heading:'Scenario-based method',body:`The test set contains twelve invented matters across personal, corporate, substituted, mail, waiver, and international-looking scenarios without attempting to model the law of any jurisdiction. Each matter has four to eight synthetic records. Seeded conditions include a recipient name mismatch, an address with two unit numbers, an attempt timestamp that precedes dispatch, a declaration missing a page, vendor status marked completed before the signed return arrives, an illegible signature, a photograph with no embedded time, returned mail, a waiver request without a response, and two documents using different time zones. One scenario includes a docket entry supplied by counsel that conflicts with a vendor portal. The population deliberately tests chronology and source hierarchy without identifying which method is legally permissible. Results describe only whether the support worker preserved and compared the supplied evidence.`},
      {heading:'Allowed facts and reserved judgments',body:`Support may record source type, document title, case identifier supplied by the firm, party name as displayed, address as displayed, server or vendor identifier as supplied, event label quoted from the source, displayed date and time, stated time zone, received timestamp, page count, signature presence as a visual observation, file hash, source path, and related instruction. It may flag conflicts, missing pages, unreadable text, absent time zones, and status changes. It must not calculate a response date, determine the correct method or recipient, choose an address, assess the server's authority, validate a signature, decide whether diligence was sufficient, call service complete, file a return, or contact a party. Words such as served, attempted, refused, waived, or completed remain attributed to the source. The record uses observed and reported states until counsel provides an authorized disposition.`},
      {heading:'Event ledger architecture',body:`A durable ledger stores each event separately rather than compressing a matter into one service-date field. It includes matter identifier, event identifier, source hash, source location, source author or issuer as displayed, document date, received date, event date, time, time zone or unknown state, address, subject name, quoted status, page reference, related prior event, exception code, reviewer, and attorney disposition. Normalized timestamps, if the firm authorizes them, sit beside originals with the conversion rule. Attachments and signed returns retain their relationship to the message or portal event that delivered them. Corrections create new versions. A matter-level view may summarize open questions, but it cannot automatically label service valid or start a deadline. This architecture acknowledges that several sources can report the same supposed event differently and that the legal significance belongs to the reviewing lawyer, not the database.`},
      {heading:'Conflicting status example',body:`Suppose a vendor portal changes a job to completed at 4:10 p.m. Eastern time. The next morning the firm receives a signed declaration displaying 3:55 p.m. but no time zone, and the address line omits a unit number contained in the instruction. A later email says the recipient confirmed identity, while the declaration uses a different spelling. Support records four separate source events, preserves the original times and labels, and flags the time-zone, address, and name differences. It does not select 3:55 or 4:10 as the service time, correct the spelling, infer identity, or mark the matter served. Counsel can review the instruction, applicable rules, vendor evidence, declaration, and any other facts. The final administrative disposition can link to counsel's instruction while retaining the raw conflict for audit. The example rewards visibility rather than false precision.`},
      {heading:'Evaluation metrics',body:`The scenario test measures event capture accuracy, source attribution, chronological ordering without destructive conversion, detection of seeded discrepancies, preservation of quoted status, attachment linkage, and unauthorized conclusions. A second reviewer reconstructs every event in three matters from the ledger. False precision is counted when an unknown time zone, illegible value, or ambiguous identity becomes a definite field. A faster chronology is not better if it drops conflicts. More completed vendor statuses do not prove valid service. Agreement between sources may increase confidence that they describe the same event, but it cannot answer whether procedural requirements were met. The report separates document-level defects, event-level conflicts, and matter-level lawyer questions. That separation shows whether support preparation is accurate without scoring the legal result or penalizing the worker because a source was incomplete.`},
      {heading:'Authority and scope of inference',body:`Federal Rule of Civil Procedure 4 and the official federal rules source provide primary procedural text for federal context. The Hague Conference Service Section supplies primary treaty resources for relevant cross-border context. Neither source makes this study a guide to service in a particular matter, and state, foreign, local, or court-specific rules may differ. ABA Formal Opinion 08-451 and Model Rule 5.3 frame outsourced nonlawyer supervision. The Philippines privacy law supplies local handling context for names, addresses, and other personal data. The source facts in this exercise come only from constructed documents. The design recommendation to preserve event-level attribution is analysis. It is reasonable to infer that visible discrepancies help counsel review the record, but the pilot cannot prove lower legal risk or procedural compliance. No listed authority endorses a vendor, staffing model, or offshore service-record process.`},
      {heading:'Limitations and control failures',body:`This research cannot determine jurisdiction, permitted method, proper recipient, valid service, waiver, diligence, cure, response deadline, default, proof sufficiency, filing need, or litigation strategy. It does not verify a process server, notary, signature, photograph, geolocation, postal event, vendor system, or docket. Synthetic scenarios omit human testimony and many real procedural variations. A file hash shows identity after capture, not truth. Translation, daylight-saving changes, ambiguous addresses, and international transmission can add complexity outside the test. Personal addresses and contact details require need-based access and controlled retention. The workflow fails if a reported status becomes an unattributed fact, if an original time is overwritten by a conversion, if a missing page is ignored, if a conflict is resolved without authority, or if an administrative status triggers a deadline or client message without lawyer review.`},
      {heading:'Practical buying conclusion',body:`A law firm can use offshore support to maintain a service evidence record when it buys careful source attribution rather than a declaration of legal completion. Start with the twelve synthetic scenarios, require the worker to preserve exact source wording, and review every seeded discrepancy with the designated lawyer. Expansion should depend on reconstruction success, correct exception ownership, and the absence of unsupported conclusions. The role needs read-only or narrowly scoped access, prohibited-action rules, and a clear urgent route that does not require the worker to calculate legal consequences. Buyers should ask how the system handles unknown time zones, competing addresses, missing pages, late declarations, and a vendor status that conflicts with the signed record. A credible answer keeps each source visible and counsel in control. The resulting chronology can reduce search and coordination work, but it remains an administrative aid rather than legal proof or advice.`}
    ],
    sources:[abaOutsourcing,model53,privacy,civilRules,{name:'Service Section, Hague Conference on Private International Law',url:'https://www.hcch.net/en/instruments/conventions/specialised-sections/service'}]
  }
];

